            passed = rendered.includes(testCase.expectedOutput);
          } else if (testCase.expectedPattern) {
            const regex = new RegExp(testCase.expectedPattern);
            passed = regex.test(rendered);
          }

          results.push({
            testCaseId: testCase.id,
            name: testCase.name,
            passed,
            duration,
            actualOutput: rendered,
            expectedOutput: testCase.expectedOutput,
          });
        } catch (error) {
          results.push({
            testCaseId: testCase.id,
            name: testCase.name,
            passed: false,
            error: error instanceof Error ? error.message : 'Unknown error',
            duration: Date.now() - startTime,
          });
        }
      }

      return results;
    } catch (error) {
      console.error('Error testing prompt:', error);
      if (error instanceof PromptServiceError) {
        throw error;
      }
      throw new PromptServiceError('Failed to test prompt', error);
    }
  }"}

