/**
 * Load JSON file
 */
function loadJSON(filename: string): any[] {
  const filePath = path.join(process.cwd(), 'migration-output', filename);

  if (!fs.existsSync(filePath)) {
    console.log(`⚠️  File not found: ${filename}`);
